46: function setEnemy(){if(depth===1){enemy={hp:46,max:46,block:0,name:'THE WALL-THAT-BREATHES',desc:'It remembers every room you left.',intent:8,type:'attack'};$('#portrait').innerHTML=svgEnemy;$('#omen').innerHTML=svgEnemy;$('#omenCaption').textContent='The plaster ripples like skin.'}else{let e=encounters[depth-2];enemy={hp:e.hp,max:e.hp,block:0,name:e.name,desc:e.desc,intent:e.attack,type:'attack'};$('#portrait').innerHTML=depth===2?svgBlind:svgMother;$('#omen').innerHTML=depth===2?svgBlind:svgMother;$('#omenCaption').textContent=depth===2?'Its face has no front.':'She rocks an empty room.'}$('#enemyName').textContent=enemy.name;$('#enemyDesc').textContent=enemy.desc;$('#intentTitle').textContent=(depth===1?'Raking fingers':encounters[depth-2].intent)+' · '+enemy.intent}
47: function render(){ $('#playerHp').textContent=player.hp;$('#playerBar').style.width=(player.hp/player.max*100)+'%';$('#playerBlock').textContent=player.block;$('#blockBar').style.width=Math.min(100,player.block*4)+'%';$('#enemyHp').textContent=enemy.hp;$('#enemyBar').style.width=(enemy.hp/enemy.max*100)+'%';$('#enemyWard').textContent=enemy.block;$('#enemyWardBar').style.width=Math.min(100,enemy.block*5)+'%';$('#energyText').textContent=player.energy+' / '+player.maxEnergy;$('#energyDots').innerHTML=Array.from({length:player.maxEnergy},(_,i)=>`<i class="${i<player.energy?'full':''}"></i>`).join('');$('#drawCount').textContent=draw.length;$('#deckCount').textContent=draw.length+discard.length+hand.length;$('#handCount').textContent=hand.length;$('#depth').textContent=String(depth).padStart(2,'0');$('#shards').textContent=shards;$('#enemyTurn').textContent=turn?'HAS STIRRED':'NOT ACTED';$('#intentMark').textContent=enemy.type==='attack'?'✹':'◈';$('#intentDesc').textContent=enemy.type==='attack'?'It will reach across the room.':'It draws a ward from the walls.';$('#cards').innerHTML='';hand.forEach((c,i)=>{let b=document.createElement('button');b.className='card';b.style.setProperty('--accent',c.kind==='guard'?'#665e4e':c.kind==='heal'?'#62705a':c.kind==='special'?'#765548':'#a53932');b.disabled=locked||player.energy<c.cost;b.innerHTML=`<div class="card-top"><span class="cost">${c.cost}</span><span class="card-type">${c.kind==='strike'?'ATTACK':c.kind==='guard'?'DEFENSE':c.kind==='heal'?'REMEDY':'RITUAL'}</span></div><div class="card-art">${cardArt[c.kind]}</div><div class="card-name">${c.name}</div><div class="card-desc">${c.text}</div><span class="card-badge">${i+1} / ${hand.length}</span>`;b.onclick=()=>playCard(i);$('#cards').appendChild(b)});$('#endTurn').disabled=locked}
48: function playCard(i){if(locked)return;let c=hand[i];if(player.energy<c.cost){showToast('NOT ENOUGH NERVE');return}player.energy-=c.cost;hand.splice(i,1);discard.push(c);if(c.damage){let dealt=Math.max(0,c.damage-enemy.block);enemy.block=Math.max(0,enemy.block-c.damage);enemy.hp-=dealt;animate('hit');showToast('THE THING LOSES '+dealt+' VITALITY')}if(c.block)player.block+=c.block;if(c.heal)player.hp=Math.min(player.max,player.hp+c.heal);if(c.draw)drawCards(c.draw);if(enemy.hp<=0){enemy.hp=0;render();setTimeout(victory,350);return}render()}
49: function animate(cls){let a=$('#arena');a.classList.remove('hit','enemy-hit');void a.offsetWidth;a.classList.add(cls);setTimeout(()=>a.classList.remove(cls),320)}
50: function endTurn(){if(locked)return;locked=true;discard.push(...hand);hand=[];if(enemy.type==='attack'){let hurt=Math.max(0,enemy.intent-player.block);let absorb=Math.min(player.block,enemy.intent);player.block-=absorb;player.hp-=hurt;animate('enemy-hit');if(hurt)showToast('THE HOUSE TAKES '+hurt)}else enemy.block+=8;player.block=0;turn++;if(player.hp<=0){player.hp=0;render();setTimeout(()=>finish(false),400);return}setTimeout(()=>{player.energy=player.maxEnergy;player.hp=Math.min(player.max,player.hp+2);enemy.intent=(depth===1?8:encounters[depth-2].attack)+Math.floor(turn/3)*2;drawCards(5);locked=false;render()},500);render()}
