52: function finish(win){locked=true;$('#modalEyebrow').textContent=win?'THE HOUSE REMEMBERS':'THE HOUSE KEEPS YOU';$('#modalTitle').textContent=win?'YOU WALK OUT':'YOU ARE FORGOTTEN';$('#modalText').textContent=win?'The dark lets go of your name. For now.':'The walls close softly. Another light appears in an upstairs window.';$('#modalButton').textContent='TRY AGAIN ↻';$('#overlay').classList.add('show');$('#modalButton').onclick=reset}
